export interface GitHubUser {
  login: string;
  id: number;
  avatar_url: string;
  name: string | null;
  type: "User" | "Organization" | "Bot" | string;
  public_repos: number;
  followers: number;
  created_at: string;
}

export interface GitHubRepo {
  name: string;
  full_name: string;
  fork: boolean;
  stargazers_count: number;
  license: { spdx_id?: string | null; name?: string | null } | null;
  created_at: string;
  pushed_at: string;
}

export interface GitHubEvent {
  id: string;
  type: string;
  created_at: string;
  repo?: { name: string };
  payload?: {
    ref?: string | null;
    ref_type?: string | null;
  };
}

export interface GitHubCommitSearchItem {
  sha: string;
  commit: {
    message: string;
    author: {
      date: string;
    };
  };
  repository?: {
    full_name: string;
  };
}

export interface GitHubCommitSearchResult {
  total_count: number;
  incomplete_results?: boolean;
  items: GitHubCommitSearchItem[];
}

export type MissingReason = number | "empty" | "error";

export interface MissingParts {
  user?: MissingReason;
  repos?: MissingReason;
  events?: MissingReason;
  commits?: MissingReason;
}

export interface GitHubBundle {
  handle: string;
  fetchedAt: string;
  preset: boolean;
  sealed?: boolean;
  user: GitHubUser | null;
  repos: GitHubRepo[];
  events: GitHubEvent[];
  commits: GitHubCommitSearchResult | null;
  missing: MissingParts;
}

